def E(x):
    return (x+2)*(x+3)*(x+4)*(x+5)+3033

r = (-7+math.sqrt(5))/2
print("root x =", r)
print("E at root (original form) =", E(r))
r2 = (-7-math.sqrt(5))/2
print("other root x =", r2, " E =", E(r2))

# dense scan
best = None
x = -50.0
while x <= 50.0:
    v = E(x)
    if best is None or v < best[0]:
        best = (v, x)
    x += 0.0001
print("scan min E =", best[0], "at x =", best[1])

# center point x = -3.5 (where t = -5/4)
print("E(-3.5) =", E(-3.5), " 25/16+3032 =", 25/16+3032)

# calculus: E'(x) = 2*t*(2x+7)
def dE(x):
    t = x*x+7*x+11
    return 2*t*(2*x+7)
for c in [r, r2, -3.5]:
    print("critical pt", c, "E'=", dE(c), "E=", E(c))
# second derivative sign at roots
def d2E(x,h=1e-5):
    return (dE(x+h)-dE(x-h))/(2*h)
for c in [r, r2, -3.5]:
    print("second deriv at", c, "=", d2E(c))
